"""Regressão JVM do LocalRecognizer real com doubles de Android/MediaPipe/Python.
Reproduz MPImage.close reciclando Bitmap; não substitui teste no aparelho.
Requer JDK 17. Uso: python test_bitmap_lifecycle.py [LocalRecognizer.java opcional]
"""
from pathlib import Path
import tempfile,subprocess,sys
ROOT=Path(__file__).resolve().parents[1]
SOURCE=Path(sys.argv[1]) if len(sys.argv)>1 else ROOT/'app/src/main/java/com/connectalibras/ia/local/LocalRecognizer.java'
files={
'android/content/Context.java': 'package android.content; public class Context { public Context getApplicationContext(){return this;} public java.io.File getFilesDir(){return new java.io.File(".");}}',
'android/graphics/Bitmap.java': '''package android.graphics; public class Bitmap {public boolean recycled; public int getWidth(){return 1;}public int getHeight(){return 1;} public boolean isRecycled(){return recycled;}public void recycle(){recycled=true;}public void getPixels(int[] p,int a,int b,int c,int d,int w,int h){if(recycled)throw new IllegalStateException("Can't call getPixels() on a recycled bitmap");p[0]=0xff123456;}}''',
'android/util/Log.java':'package android.util; public class Log { public static int w(String a,String b,Throwable c){return 0;}}',
'com/chaquo/python/android/AndroidPlatform.java':'package com.chaquo.python.android; public class AndroidPlatform {public AndroidPlatform(android.content.Context c){}}',
'com/chaquo/python/Python.java':'''package com.chaquo.python; public class Python {public static int calls;public static boolean isStarted(){return true;}public static void start(Object p){} public static Python getInstance(){return new Python();}public PyObject getModule(String n){return new PyObject();}}''',
'com/chaquo/python/PyObject.java':'''package com.chaquo.python; public class PyObject {public PyObject callAttr(String name,Object...args){if(name.equals("reconhecer_json")){byte[] p=(byte[])args[0];if(p.length!=3||p[0]!=0x12||p[1]!=0x34||p[2]!=0x56)throw new AssertionError("RGB alterado");Python.calls++;}return new PyObject();}public String toString(){return "{}";}}''',
'org/json/JSONObject.java':'''package org.json; public class JSONObject {public JSONObject(String s){}public String getString(String n){return n.equals("nome")?"teste":n.equals("versao")?"v1":"";}public double getDouble(String n){return 0;}public boolean getBoolean(String n){return false;}}''',
'com/google/mediapipe/framework/image/MPImage.java':'''package com.google.mediapipe.framework.image; public class MPImage {public static int closes;public final android.graphics.Bitmap bitmap;public MPImage(android.graphics.Bitmap b){bitmap=b;}public void close(){closes++;bitmap.recycle();}}''',
'com/google/mediapipe/framework/image/BitmapImageBuilder.java':'''package com.google.mediapipe.framework.image; public class BitmapImageBuilder {private android.graphics.Bitmap bitmap;public BitmapImageBuilder(android.graphics.Bitmap b){bitmap=b;}public MPImage build(){return new MPImage(bitmap);}}''',
'com/google/mediapipe/tasks/core/BaseOptions.java':'''package com.google.mediapipe.tasks.core; public class BaseOptions {public static Builder builder(){return new Builder();}public static class Builder {public Builder setModelAssetPath(String n){return this;}public BaseOptions build(){return new BaseOptions();}}}''',
'com/google/mediapipe/tasks/vision/core/RunningMode.java':'package com.google.mediapipe.tasks.vision.core; public enum RunningMode {VIDEO}',
'com/google/mediapipe/tasks/components/containers/NormalizedLandmark.java':'package com.google.mediapipe.tasks.components.containers; public class NormalizedLandmark {public float x(){return 0;}public float y(){return 0;}public float z(){return 0;}}',
'com/google/mediapipe/tasks/components/containers/Category.java':'package com.google.mediapipe.tasks.components.containers; public class Category {public String categoryName(){return "left";}}',
'com/google/mediapipe/tasks/vision/handlandmarker/HandLandmarkerResult.java':'''package com.google.mediapipe.tasks.vision.handlandmarker; import java.util.*;import com.google.mediapipe.tasks.components.containers.*;public class HandLandmarkerResult {public List<List<NormalizedLandmark>> landmarks(){return Collections.emptyList();}public List<List<Category>> handedness(){return Collections.emptyList();}}''',
'com/google/mediapipe/tasks/vision/handlandmarker/HandLandmarker.java':'''package com.google.mediapipe.tasks.vision.handlandmarker;public class HandLandmarker {public static boolean fail;public static HandLandmarker createFromOptions(Object c,HandLandmarkerOptions o){return new HandLandmarker();}public HandLandmarkerResult detectForVideo(com.google.mediapipe.framework.image.MPImage image,long stamp){if(image.bitmap.isRecycled())throw new AssertionError("Frame reciclado antes da detecção");if(fail)throw new IllegalStateException("falha simulada");return new HandLandmarkerResult();}public void close(){} public static class HandLandmarkerOptions {public static Builder builder(){return new Builder();}public static class Builder {public Builder setBaseOptions(Object o){return this;}public Builder setRunningMode(Object o){return this;}public Builder setNumHands(int n){return this;}public Builder setMinHandDetectionConfidence(float n){return this;}public Builder setMinHandPresenceConfidence(float n){return this;}public Builder setMinTrackingConfidence(float n){return this;}public HandLandmarkerOptions build(){return new HandLandmarkerOptions();}}}}''',
'RunBitmapTest.java':'''import android.graphics.Bitmap;import com.connectalibras.ia.local.*;import com.google.mediapipe.tasks.vision.handlandmarker.HandLandmarker;import com.google.mediapipe.framework.image.MPImage;import com.chaquo.python.Python;public class RunBitmapTest {public static void main(String[] args)throws Exception {LocalRecognizer r=new LocalRecognizer(new android.content.Context());for(int i=0;i<200;i++){Bitmap b=new Bitmap();r.process(b,1000+i,"AUTO");if(!b.isRecycled())throw new AssertionError("MPImage não fechou");}if(Python.calls!=200||MPImage.closes!=200)throw new AssertionError("Contagem errada");Bitmap failed=new Bitmap();HandLandmarker.fail=true;try{r.process(failed,2000,"AUTO");throw new AssertionError("Falha não propagada");}catch(IllegalStateException e){if(!failed.isRecycled())throw new AssertionError("Vazamento em falha");}r.close();r.close();try{r.process(new Bitmap(),3000,"AUTO");throw new AssertionError("Sessão fechada aceitou frame");}catch(IllegalStateException expected){}System.out.println("BITMAP_LIFECYCLE_PASS: 200 frames RGB, fechamento em falha e sessão encerrada");}}'''
}
with tempfile.TemporaryDirectory(prefix='connecta-bitmap-test-') as temp:
    root=Path(temp)
    for name,code in files.items():
        f=root/name;f.parent.mkdir(parents=True,exist_ok=True);f.write_text(code)
    for name in ('LocalRecognizer','RecognitionResult'):
        f=root/'com/connectalibras/ia/local'/f'{name}.java';f.parent.mkdir(parents=True,exist_ok=True)
        original=SOURCE if name=='LocalRecognizer' else ROOT/'app/src/main/java/com/connectalibras/ia/local/RecognitionResult.java'
        f.write_bytes(original.read_bytes())
    subprocess.run(['java','com.sun.tools.javac.Main','-d',str(root/'classes'),*[str(f) for f in root.rglob('*.java')]],check=True)
    subprocess.run(['java','-cp',str(root/'classes'),'RunBitmapTest'],check=True)
